/**
 * PWDatabase Live Service
 * Fetches and parses authentic entity details directly from jd.pwdatabase.com
 * through the local Vite proxy (/api/pwdb/pwi/...).
 */

export interface PwdbTableData {
  title: string;
  headers: string[];
  rows: Array<Array<{ text: string; link?: string; icon?: string }>>;
}

export interface PwdbRefineRow {
  level: string;
  effect: string;
}

export interface PwdbEntityData {
  id: number;
  type: 'item' | 'mob' | 'npc' | 'quest';
  name: string;
  icon?: string;
  priceText?: string;
  stackLimit?: string;
  itemType?: string;
  reqLevel?: string;
  effectText?: string;
  loreDescription?: string;
  equipProps?: string[];

  // Monster Stats
  hp?: string;
  mp?: string;
  exp?: string;
  gold?: string;
  attack?: string;
  defence?: string;
  critRate?: string;
  critDamage?: string;
  accuracy?: string;
  evasion?: string;
  attackRange?: string;
  aggressive?: string;
  agroTime?: string;
  agroRange?: string;
  mobType?: string;
  mobLevel?: string;
  resistances?: {
    stun?: string;
    weaken?: string;
    paralyze?: string;
    silence?: string;
    sleep?: string;
  };
  protections?: {
    critRateDec?: string;
    critDmgDec?: string;
    skillEvasion?: string;
    skillAccuracy?: string;
  };
  mobLocations?: string;

  // NPC Info
  invitationMessage?: string;
  npcServices?: string[];
  npcLocation?: string;

  // Quest Info
  givenBy?: { name: string; link?: string };
  takenTo?: { name: string; link?: string };
  dialog?: string;
  questDescription?: string;
  questObjectives?: string[];
  questAwards?: Array<{ name: string; link?: string; icon?: string }>;

  // Tables
  refineRows?: PwdbRefineRow[];
  dropFromTable?: PwdbTableData;
  soldByTable?: PwdbTableData;
  usedInQuestsTable?: PwdbTableData;
  uniqueDropsTable?: PwdbTableData;
  npcQuestsTable?: PwdbTableData;
  tables: PwdbTableData[];
  rawInfoText?: string;
}

