function getPersistentCache(key: string): PwdbEntityData | null {
  if (memoryCache.has(key)) {
    return memoryCache.get(key)!;
  }
  if (BUNDLED_CACHE[key]) {
    const b = BUNDLED_CACHE[key] as PwdbEntityData;
    memoryCache.set(key, b);
    return b;
  }
  try {
    const raw = localStorage.getItem(CACHE_PREFIX + key);
    if (raw) {
      const data = JSON.parse(raw) as PwdbEntityData;
      memoryCache.set(key, data);
      return data;
    }
  } catch (_) {}
  return null;
}

function setPersistentCache(key: string, data: PwdbEntityData): void {
  memoryCache.set(key, data);
  try {
    localStorage.setItem(CACHE_PREFIX + key, JSON.stringify(data));
  } catch (_) {
    // If quota exceeded, evict older cache entries
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(CACHE_PREFIX)) {
          localStorage.removeItem(k);
        }
      }
      localStorage.setItem(CACHE_PREFIX + key, JSON.stringify(data));
    } catch (_) {}
  }
}

export class PwdbService {
  /**
   * Returns cached entity data immediately if available (BUNDLED_CACHE, memory, or localStorage).
   */
  public static getCachedEntity(
    type: 'item' | 'mob' | 'npc' | 'quest',
    id: number
  ): PwdbEntityData | null {
    return getPersistentCache(`${type}_${id}`);
  }

  /**
   * Fetches and parses authentic data for an entity from PWDatabase.
   * Leverages persistent localStorage caching for instant 0ms retrieval.
   */
  public static async fetchEntity(
    type: 'item' | 'mob' | 'npc' | 'quest',
    id: number
  ): Promise<PwdbEntityData | null> {
    const cacheKey = `${type}_${id}`;
    const cached = getPersistentCache(cacheKey);
    if (cached) {
      return cached;
    }

    for (let attempt = 1; attempt <= 2; attempt++) {
      try {
        const url = `/api/pwdb/pwi/${type}/${id}`;
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 10000);

        const resp = await fetch(url, {
          signal: controller.signal,
          headers: {
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
          }
        });
        clearTimeout(timeoutId);

        if (!resp.ok) {
          if (attempt === 2) {
            console.warn(`PWDatabase live fetch returned HTTP ${resp.status} for ${type}/${id}`);
            return null;
          }
          await new Promise(r => setTimeout(r, 400));
          continue;
        }

        const html = await resp.text();
        const parsed = this.parseHtml(type, id, html);
        if (parsed) {
          setPersistentCache(cacheKey, parsed);
        }
        return parsed;
      } catch (err: any) {
        if (attempt === 2) {
          console.warn(`PWDatabase live fetch error for ${type}/${id}:`, err?.message || err);
          return null;
        }
        await new Promise(r => setTimeout(r, 400));
      }
    }
    return null;
  }

  private static parseHtml(
    type: 'item' | 'mob' | 'npc' | 'quest',
    id: number,
    html: string
  ): PwdbEntityData | null {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    const content = doc.querySelector('#content') || doc.body;

    // Helper to normalize image URLs from pwdatabase
    const normalizeImg = (src: string | null | undefined) => {
      if (!src) return undefined;
      if (src.startsWith('http')) return src;
      return `https://jd.pwdatabase.com${src.startsWith('/') ? '' : '/'}${src}`;
    };

    // Helper to normalize links from pwdatabase
    const normalizeLink = (href: string | null | undefined): string | undefined => {
      if (!href) return undefined;
      if (href.startsWith('http')) return href;
      const clean = href.replace(/^\/?(?:pwi\/)?/, '');
      return `https://jd.pwdatabase.com/pwi/${clean}`;
    };

    // Helper to clone element with linebreaks converted to real newlines
    const extractCleanText = (el: Element | null): string => {
      if (!el) return '';
      const clone = el.cloneNode(true) as HTMLElement;
      clone.querySelectorAll('script, style').forEach(s => s.remove());
      clone.querySelectorAll('br').forEach(br => br.replaceWith('\n'));
      clone.querySelectorAll('p, div, tr, th, td, h1, h2, h3').forEach(block => block.prepend('\n'));
      return (clone.textContent || '').replace(/\r/g, '').replace(/[ \t]+/g, ' ');
    };

    const fullContentText = extractCleanText(content);

    // Title / Header
    const headerEl = content.querySelector('.header') || doc.querySelector('.plain .header');
    let name = '';
    let icon = '';
    if (headerEl) {
      const img = headerEl.querySelector('img');
      if (img) icon = normalizeImg(img.getAttribute('src')) || '';
      name = headerEl.textContent?.replace(/\s+/g, ' ').trim() || '';
    }

    if (!name) {
      const thEl = content.querySelector('table th');
      if (thEl) {
        name = thEl.textContent?.replace(/\s+/g, ' ').trim() || '';
      } else {
        const titleEl = doc.querySelector('title');
        name = titleEl?.textContent?.replace(/\s*-\s*Jade Dynasty.*$/i, '').trim() || '';
      }
    }

    // Helper regex match from fullContentText
    const matchStat = (regex: RegExp): string | undefined => {
      const m = fullContentText.match(regex);
      return m ? m[1].trim() : undefined;
    };

    // ==========================================
    // 1. ITEM PARSING
    // ==========================================
    let priceText: string | undefined;
    let stackLimit: string | undefined;
    let itemType: string | undefined;
    let reqLevel: string | undefined;
    let effectText: string | undefined;
    let loreDescription: string | undefined;
    const equipProps: string[] = [];

    if (type === 'item') {
      priceText = matchStat(/Price:\s*([^\n\r]+)/i);
      stackLimit = matchStat(/Stacked:\s*([^\n\r]+)/i);
      itemType = matchStat(/Type:\s*([^\n\r]+)/i);
      reqLevel = matchStat(/(?:Required )?Level:\s*([^\n\r]+)/i);

      // Weapon / Armor stats
      const atkProp = matchStat(/Attack Power:\s*([^\n\r]+)/i);
      if (atkProp) equipProps.push(`Attack Power: ${atkProp}`);
      const defProp = matchStat(/Defense:\s*([^\n\r]+)/i);
      if (defProp) equipProps.push(`Defense: ${defProp}`);
      const rangeProp = matchStat(/Range:\s*([^\n\r]+)/i);
      if (rangeProp) equipProps.push(`Range: ${rangeProp}`);
      const factionProp = matchStat(/Required Faction:\s*([^\n\r]+)/i);
      if (factionProp) equipProps.push(`Required Faction: ${factionProp}`);

      // Effect
      const effMatch = fullContentText.match(/Effect:\s*([^\n\r]+(?:\n[^\n\r]+)?)/i);
      if (effMatch) {
        effectText = effMatch[1].trim().replace(/\n+/g, ' ');
      }

      // Lore Description
      const infoEl = content.querySelector('.info');
      if (infoEl) {
        const pTags = Array.from(infoEl.querySelectorAll('p, div'));
        for (const p of pTags) {
          const t = p.textContent?.trim() || '';
          if (
            (t.includes('Right-click to') || t.startsWith('A ') || t.length > 30) &&
            !t.startsWith('Price:') &&
            !t.startsWith('Stacked:') &&
            !t.startsWith('Type:') &&
            !t.startsWith('Required') &&
            !t.startsWith('Effect:')
          ) {
            loreDescription = t;
            break;
          }
        }
      }
    }

    // ==========================================
    // 2. MONSTER PARSING
    // ==========================================
    let hp: string | undefined;
    let mp: string | undefined;
    let exp: string | undefined;
    let gold: string | undefined;
    let attack: string | undefined;
    let defence: string | undefined;
    let critRate: string | undefined;
    let critDamage: string | undefined;
    let accuracy: string | undefined;
    let evasion: string | undefined;
    let attackRange: string | undefined;
    let aggressive: string | undefined;
    let agroTime: string | undefined;
    let agroRange: string | undefined;
    let mobType: string | undefined;
    let mobLevel: string | undefined;
    let resistances: { stun?: string; weaken?: string; paralyze?: string; silence?: string; sleep?: string } | undefined;
    let protections: { critRateDec?: string; critDmgDec?: string; skillEvasion?: string; skillAccuracy?: string } | undefined;
    let mobLocations: string | undefined;

    if (type === 'mob') {
      hp = matchStat(/\bHP\s*[:\n\r\s]+(\d+)/i);
      mp = matchStat(/\bMana\s*[:\n\r\s]+(\d+)/i);
      attack = matchStat(/\bAttack Power\s*[:\n\r\s]+([^\n\r]+)/i);
      defence = matchStat(/\bDefence\s*[:\n\r\s]+(\d+)/i);
      exp = matchStat(/\bExp\s*[:\n\r\s]+(\d+)/i);
      gold = matchStat(/\bGold\s*[:\n\r\s]+([^\n\r]+)/i);
      mobLevel = matchStat(/\bLevel\s*[:\n\r\s]+(\d+)/i);
      mobType = matchStat(/\bType\s*[:\n\r\s]+([^\n\r]+)/i);
      aggressive = matchStat(/\bAggressive\s*[:\n\r\s]+(Yes|No)/i);
      agroTime = matchStat(/\bAgro time\s*[:\n\r\s]+([^\n\r]+)/i);
      agroRange = matchStat(/\bAgro range\s*[:\n\r\s]+([^\n\r]+)/i);

      critRate = matchStat(/\bCritical rate\s*[:\n\r\s]+([^\n\r]+)/i);
      critDamage = matchStat(/\bCrit\. damage\s*[:\n\r\s]+([^\n\r]+)/i);
      accuracy = matchStat(/\bAccuracy\s*[:\n\r\s]+([^\n\r]+)/i);
      evasion = matchStat(/\bEvasion\s*[:\n\r\s]+([^\n\r]+)/i);
      attackRange = matchStat(/\bAttack Range\s*[:\n\r\s]+([^\n\r]+)/i);

      resistances = {
        stun: matchStat(/Stun Resistance\s*[:\n\r\s]+(\d+)/i) || '0',
        weaken: matchStat(/Weaken Resistance\s*[:\n\r\s]+(\d+)/i) || '0',
        paralyze: matchStat(/Paralyze Resistance\s*[:\n\r\s]+(\d+)/i) || '0',
        silence: matchStat(/Silence Resistance\s*[:\n\r\s]+(\d+)/i) || '0',
        sleep: matchStat(/Sleep Resistance\s*[:\n\r\s]+(\d+)/i) || '0'
      };

      protections = {
        critRateDec: matchStat(/Crit rate decrease\s*[:\n\r\s]+(\d+)/i) || '0',
        critDmgDec: matchStat(/Crit damage decrease\s*[:\n\r\s]+(\d+)/i) || '0',
        skillEvasion: matchStat(/Skill evasion\s*[:\n\r\s]+(\d+)/i) || '0',
        skillAccuracy: matchStat(/Skill accuracy\s*[:\n\r\s]+(\d+)/i) || '0'
      };

      // City & Spawn Coordinates
      const spawnMatch = fullContentText.match(/(?:Sunstream|Jadeon|Skysong|Doom Bog|Wildlands|Incense Valley|Southern Border|Kunlun|Shura|Dragon Mountain|Athan|Divine Realm|Underworld)[^:\n\r]*[:\s\n\r]+((?:-?\d{1,4}\s+-?\d{1,4}(?:\(\d+\))?[;,\s]*)+)/i);
      if (spawnMatch) {
        mobLocations = spawnMatch[0].trim().replace(/\n+/g, ': ');
      }
      if (!mobLocations) {
        const cMatch = fullContentText.match(/(?:Spawn|Coordinates|Location|Found in)\s*[:\s]+([^\n\r]+)/i);
        if (cMatch && !/^(?:yes|no|none|n\/a)$/i.test(cMatch[1].trim())) {
          mobLocations = cMatch[1].trim();
        }
      }
      if (!mobLocations) {
        const mapEl = Array.from(content.querySelectorAll('div, td, span')).find(el => {
          const t = el.textContent?.trim() || '';
          return /(?:Sunstream|Jadeon|Skysong|Doom Bog|Wildlands|Incense Valley|Southern Border|Kunlun|Shura|Dragon Mountain)/i.test(t) && /[-\d]{1,4}\s+[-\d]{1,4}/.test(t);
        });
        if (mapEl) {
          mobLocations = mapEl.textContent?.replace(/\s+/g, ' ').trim();
        }
      }
    }

    // ==========================================
    // 3. NPC PARSING
    // ==========================================
    let invitationMessage: string | undefined;
    const npcServices: string[] = [];
    let npcLocation: string | undefined;

    if (type === 'npc') {
      const invM = fullContentText.match(/Invitation Message\s*[:\n\r\s]+([\s\S]*?)(?=\n\s*(?:Main Info|Location|Display mode|$))/i);
      if (invM) {
        invitationMessage = invM[1].trim().replace(/\s+/g, ' ');
      }

      // Services - only display if value is "Yes"
      if (/Give access to the bank:\s*Yes/i.test(fullContentText)) npcServices.push('Bank & Warehouse Access');
      if (/Selling items:\s*Yes/i.test(fullContentText)) npcServices.push('Equipment & Goods Merchant');
      if (/Can teleport to other location:\s*Yes/i.test(fullContentText)) npcServices.push('Teleportation Service');
      if (/Reset stat service:\s*Yes/i.test(fullContentText)) npcServices.push('Stat Reset Service');
      if (/Merge seal service:\s*Yes/i.test(fullContentText)) npcServices.push('Merge Seal Service');

      // Look for authentic territory/location strings, avoiding "Can teleport to other location: No"
      const locM = fullContentText.match(/(?:^|\n)\s*(?:Location|Territory|Stationed)\s*[:\s]+([^\n\r]+)/i);
      if (locM) {
        const val = locM[1].trim();
        if (!/^(?:yes|no|none|n\/a)$/i.test(val) && !val.toLowerCase().includes('teleport')) {
          npcLocation = val;
        }
      }
    }

    // ==========================================
    // 4. QUEST PARSING
    // ==========================================
    let givenBy: { name: string; link?: string } | undefined;
    let takenTo: { name: string; link?: string } | undefined;
    let dialog: string | undefined;
    let questDescription: string | undefined;
    const questObjectives: string[] = [];
    const questAwards: Array<{ name: string; link?: string; icon?: string }> = [];

    if (type === 'quest') {
      // Story / Description
      const descM = fullContentText.match(/Description\s*[:\n\r\s]+([\s\S]*?)(?=\n\s*(?:Kill:|Collect:|Reach:|Obtain:|Investigate:|Award Item|NPC|Require|Quest Stats|Dialogs:|$))/i);
      if (descM && descM[1].trim()) {
        questDescription = descM[1].trim().replace(/\s+/g, ' ');
      }

      // Objectives (Kill, Collect, Reach, Obtain, Investigate)
      const objMatches = fullContentText.match(/(?:Kill|Collect|Reach|Obtain|Investigate):\s*([^\n\r]+)/gi);
      if (objMatches) {
        for (const o of objMatches) {
          const cleaned = o.trim().replace(/\s+/g, ' ');
          if (!questObjectives.includes(cleaned)) {
            questObjectives.push(cleaned);
          }
        }
      }

      // NPCs (Starting & Award NPC)
      const npcLinks = Array.from(content.querySelectorAll('a')).filter(a => {
        const h = a.getAttribute('href') || '';
        return h.includes('npc/') || h.includes('/npc/');
      });

      if (npcLinks.length >= 1) {
        const a = npcLinks[0];
        const link = normalizeLink(a.getAttribute('href'));
        const parentText = a.parentElement?.textContent || '';
        const locM = parentText.match(/"([^"]+)"\s*([\d\s\(\)]+)/);
        const locStr = locM ? ` ("${locM[1]}" ${locM[2].trim()})` : '';
        givenBy = { name: `${a.textContent?.trim() || 'Starting NPC'}${locStr}`, link };
      }

      if (npcLinks.length >= 2) {
        const a = npcLinks[1];
        const link = normalizeLink(a.getAttribute('href'));
        const parentText = a.parentElement?.textContent || '';
        const locM = parentText.match(/"([^"]+)"\s*([\d\s\(\)]+)/);
        const locStr = locM ? ` ("${locM[1]}" ${locM[2].trim()})` : '';
        takenTo = { name: `${a.textContent?.trim() || 'Turn-in NPC'}${locStr}`, link };
      }

      // Award Items
      const itemLinks = Array.from(content.querySelectorAll('a')).filter(a => {
        const h = a.getAttribute('href') || '';
        return h.includes('item/') || h.includes('/item/');
      });

      for (const a of itemLinks) {
        const itemName = a.textContent?.trim() || '';
        if (itemName && !questAwards.some(x => x.name === itemName)) {
          const img = a.querySelector('img') || a.parentElement?.querySelector('img') || a.previousElementSibling;
          const iconSrc = img && (img as HTMLElement).tagName === 'IMG' ? (img as HTMLImageElement).getAttribute('src') : undefined;
          questAwards.push({
            name: itemName,
            link: normalizeLink(a.getAttribute('href')),
            icon: normalizeImg(iconSrc)
          });
        }
      }

      // Dialogs
      const dMatch = fullContentText.match(/(?:Finishing Quest:|Dialogs:)\s*[:\n\r\s]+([\s\S]*?)(?=\n\s*(?:JD Database|Jady Dynasty|$))/i);
      if (dMatch && dMatch[1].trim()) {
        dialog = dMatch[1].trim().replace(/\n+/g, '\n');
      }
    }

    // ==========================================
    // 5. TABLE PARSING & SPECIAL TABLES
    // ==========================================
    const tables: PwdbTableData[] = [];
    let dropFromTable: PwdbTableData | undefined;
    let soldByTable: PwdbTableData | undefined;
    let usedInQuestsTable: PwdbTableData | undefined;
    let uniqueDropsTable: PwdbTableData | undefined;
    let npcQuestsTable: PwdbTableData | undefined;
    const refineRows: PwdbRefineRow[] = [];

    // Refine table parsing (for gear improvement)
    const refineSectionMatch = fullContentText.match(/(?:Refine|Refinement)(?:\s+(?:Defend|Defense|Attack Power|Attack|Def|Atk))?[\s\S]*?(?=\n\s*(?:Used in quests|Sold|Drop from|Item can be exchanged|Award from quest|$))/i);
    if (refineSectionMatch) {
      const sectionText = refineSectionMatch[0];
      const lineMatches = Array.from(sectionText.matchAll(/(?:^|\n|\s)(\d{1,2}):\s*([+-\d]+[^\n\r]*)/g));
      for (const lm of lineMatches) {
        const lvl = parseInt(lm[1], 10);
        if (lvl >= 1 && lvl <= 20) {
          const eff = lm[2].trim();
          refineRows.push({ level: `+${lvl}`, effect: eff.startsWith('+') ? eff : `+${eff}` });
        }
      }
    }

    if (refineRows.length === 0) {
      const allEls = Array.from(content.querySelectorAll('th, td, div, b, strong, p'));
      for (const el of allEls) {
        const text = el.textContent?.trim() || '';
        if (/^Refine$/i.test(text) || (/Refine/i.test(text) && /\b1:\s*\+?\d+/.test(text))) {
          const container = el.closest('td, div, table') || el.parentElement || el;
          const rText = extractCleanText(container);
          const rMatches = Array.from(rText.matchAll(/(?:^|\n|\s)(\d{1,2}):\s*([+-\d]+)/g));
          if (rMatches.length >= 2) {
            for (const rm of rMatches) {
              const lvl = parseInt(rm[1], 10);
              if (lvl >= 1 && lvl <= 20) {
                refineRows.push({ level: `+${lvl}`, effect: `+${rm[2].replace(/^\+/, '')}` });
              }
            }
            if (refineRows.length > 0) break;
          }
        }
      }
    }

    // All structured tables
    const tableElements = Array.from(content.querySelectorAll('table.list, table.listitems, table'));

    for (const tbl of tableElements) {
      // Determine table title
      let title = '';
      let prevEl = tbl.previousElementSibling;
      while (prevEl && !title) {
        const t = prevEl.textContent?.replace(/\s+/g, ' ').trim() || '';
        if (t && (prevEl.classList.contains('tableHeader') || prevEl.tagName === 'H3' || prevEl.tagName === 'DIV' || prevEl.tagName === 'B')) {
          if (/drop|sold|vendor|quest|goods|item|merchandise/i.test(t)) {
            title = t;
            break;
          }
        }
        prevEl = prevEl.previousElementSibling;
      }
      if (!title) {
        const th = tbl.querySelector('tr th');
        if (th && !tbl.querySelector('tr th:nth-child(2)')) {
          title = th.textContent?.replace(/\s+/g, ' ').trim() || '';
        }
      }
      if (!title && tbl.previousElementSibling) {
        title = tbl.previousElementSibling.textContent?.replace(/\s+/g, ' ').trim() || '';
      }

      const headers: string[] = [];
      tbl.querySelectorAll('tr th').forEach(h => {
        const ht = h.textContent?.replace(/\s+/g, ' ').trim() || '';
        if (ht) headers.push(ht);
      });
      const headersJoined = headers.map(h => h.toLowerCase()).join(' ');
      if (!title) {
        if (headersJoined.includes('discount')) title = 'Sold';
        else if (headersJoined.includes('rate') || headersJoined.includes('%')) title = 'Drop from';
      }
      if (!title || title.toLowerCase().includes('search') || title.toLowerCase().includes('not found')) continue;

      const rows: Array<Array<{ text: string; link?: string; icon?: string }>> = [];
      const seenRows = new Set<string>();

      tbl.querySelectorAll('tr').forEach(tr => {
        if (tr.querySelector('th') && headers.length > 0) return; // Header row
        const rowCells: Array<{ text: string; link?: string; icon?: string }> = [];
        tr.querySelectorAll('td').forEach((td, cIdx) => {
          const a = td.querySelector('a');
          const img = td.querySelector('img');
          let text = td.textContent?.replace(/\s+/g, ' ').trim() || '';
          const colHeader = (headers[cIdx] || '').toLowerCase();
          if ((colHeader.includes('%') || colHeader.includes('rate')) && text && !text.includes('%') && /^\d+(\.\d+)?$/.test(text)) {
            text = `${text}%`;
          }
          rowCells.push({
            text,
            link: normalizeLink(a?.getAttribute('href')),
            icon: normalizeImg(img?.getAttribute('src'))
          });
        });

        if (rowCells.length === 0) return;

        // Filter out Chinese / non-English rows
        const hasChinese = rowCells.some(c => /[\u4e00-\u9fa5]/.test(c.text));
        if (hasChinese) return;

        // Filter out N/A dummy rows
        const firstText = rowCells[0]?.text || '';
        if (firstText.startsWith('N/A') || firstText.toLowerCase() === 'n/a' || firstText === '-') return;

        // Deduplicate rows
        const dedupeKey = rowCells.map(c => c.text).join('|');
        if (seenRows.has(dedupeKey)) return;
        seenRows.add(dedupeKey);

        rows.push(rowCells);
      });

      if (rows.length > 0) {
        const tableObj: PwdbTableData = { title, headers, rows };
        const tLower = title.toLowerCase();
        const headersJoined = headers.map(h => h.toLowerCase()).join(' ');

        if (type === 'item') {
          if (
            tLower.includes('drop') || 
            tLower.includes('loot') || 
            (headersJoined.includes('level') && headersJoined.includes('map') && headersJoined.includes('%'))
          ) {
            dropFromTable = tableObj;
          } else if (
            tLower === 'sold' ||
            tLower.includes('sold') || 
            tLower.includes('vendor') || 
            tLower.includes('merchant') || 
            tLower.includes('shop') || 
            tLower.includes('goods') || 
            tLower.includes('selling') || 
            headersJoined.includes('discount') || 
            (headersJoined.includes('coordinates') && headersJoined.includes('map') && !headersJoined.includes('hp'))
          ) {
            soldByTable = tableObj;
          } else if (tLower.includes('used in quests')) {
            usedInQuestsTable = tableObj;
          }
        } else if (type === 'mob') {
          if (tLower.includes('drop') || tLower.includes('loot')) {
            // Deduplicate items dropped by monster so each item is unique
            const uniqueItems = new Map<string, typeof rows[0]>();
            for (const r of rows) {
              const itemName = r[0]?.text || '';
              if (itemName && !uniqueItems.has(itemName.toLowerCase())) {
                uniqueItems.set(itemName.toLowerCase(), r);
              }
            }
            uniqueDropsTable = { title, headers, rows: Array.from(uniqueItems.values()) };
          }
        } else if (type === 'npc') {
          if (tLower.includes('sold') || tLower.includes('goods') || tLower.includes('selling') || tLower.includes('merchandise')) {
            soldByTable = tableObj;
          } else if (tLower.includes('quest') || headersJoined.includes('quest')) {
            npcQuestsTable = tableObj;
          }
        }

        tables.push(tableObj);
      }
    }

    return {
      id,
      type,
      name,
      icon,
      priceText,
      stackLimit,
      itemType,
      reqLevel,
      effectText,
      loreDescription,
      equipProps,
      hp,
      mp,
      exp,
      gold,
      attack,
      defence,
      critRate,
      critDamage,
      accuracy,
      evasion,
      attackRange,
      aggressive,
      agroTime,
      agroRange,
      mobType,
      mobLevel,
      resistances,
      protections,
      mobLocations,
      invitationMessage,
      npcServices,
      npcLocation,
      givenBy,
      takenTo,
      dialog,
      questDescription,
      questObjectives,
      questAwards,
      refineRows: refineRows.length > 0 ? refineRows : undefined,
      dropFromTable,
      soldByTable,
      usedInQuestsTable,
      uniqueDropsTable,
      npcQuestsTable,
      tables,
      rawInfoText: fullContentText
    };
  }
}
