import { ClassDefinition, TierDefinition } from '../../types/skill.ts';
import { SkillEngine } from '../../engine/SkillEngine.ts';
import { SkillNode } from './SkillNode.ts';

export class SkillTreeRenderer {
  private container: HTMLElement;
  private engine: SkillEngine;
  private skillNodes: SkillNode[] = [];
  private activeMobileTier: number | 'all' = 'all';
  private resizeObserver: ResizeObserver | null = null;
  private resizeListener: (() => void) | null = null;

  constructor(container: HTMLElement, engine: SkillEngine) {
    this.container = container;
    this.engine = engine;
    this.engine.subscribe(this.onEngineUpdate.bind(this));
    this.render();
  }

  public setEngine(engine: SkillEngine) {
    this.engine = engine;
    this.engine.subscribe(this.onEngineUpdate.bind(this));
    this.render();
  }

  public render() {
    this.container.innerHTML = '';
    this.skillNodes = [];

    const classDef = this.engine.getClassDefinition();

    // Mobile Tier Navigation Bar (visible only on mobile via CSS)
    const mobileBar = document.createElement('div');
    mobileBar.className = 'mobile-tier-bar';

    const allBtn = document.createElement('button');
    allBtn.className = `mobile-tier-btn ${this.activeMobileTier === 'all' ? 'active' : ''}`;
    allBtn.textContent = 'All Tiers';
    allBtn.addEventListener('click', () => {
      this.activeMobileTier = 'all';
      treeGrid.dataset.mobileFilter = 'all';
      this.updateMobileBarActiveState(mobileBar);
      requestAnimationFrame(() => this.updateConnectorPositions());
    });
    mobileBar.appendChild(allBtn);

    for (const tier of classDef.tiers) {
      const btn = document.createElement('button');
      btn.className = `mobile-tier-btn ${this.activeMobileTier === tier.tier ? 'active' : ''}`;
      btn.dataset.tierNum = String(tier.tier);
      const shortName = tier.tier === 0 ? 'Init' : `T${tier.tier}`;
      btn.innerHTML = `<span>${shortName}</span> <span class="mobile-tier-pts" id="mobile-tier-pts-${tier.tier}">(${this.engine.getTierPoints(tier.tier)})</span>`;
      btn.addEventListener('click', () => {
        this.activeMobileTier = tier.tier;
        treeGrid.dataset.mobileFilter = String(tier.tier);
        this.updateMobileBarActiveState(mobileBar);
        requestAnimationFrame(() => this.updateConnectorPositions());
      });
      mobileBar.appendChild(btn);
    }

    this.container.appendChild(mobileBar);

    // Skill Tree Grid
    const treeGrid = document.createElement('div');
    treeGrid.className = 'skill-tree-grid';
    treeGrid.dataset.mobileFilter = String(this.activeMobileTier);

    for (const tier of classDef.tiers) {
      const tierCol = this.renderTierColumn(tier, classDef);
      treeGrid.appendChild(tierCol);
    }

    treeGrid.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      if (!target.closest('.skill-node') && !target.closest('button')) {
        if (this.engine.getSynergyHighlight()) {
          this.engine.clearSynergyHighlight();
        }
      }
    });

    this.container.appendChild(treeGrid);

    this.setupResizeHandlers();

    requestAnimationFrame(() => {
      this.updateConnectorPositions();
      this.updateConnectorStates();
    });
    setTimeout(() => {
      this.updateConnectorPositions();
    }, 80);
  }

  private setupResizeHandlers() {
    if (this.resizeListener) {
      window.removeEventListener('resize', this.resizeListener);
      this.resizeListener = null;
    }
    if (this.resizeObserver) {
      this.resizeObserver.disconnect();
      this.resizeObserver = null;
    }

    this.resizeListener = () => {
      this.updateConnectorPositions();
    };
    window.addEventListener('resize', this.resizeListener, { passive: true });

    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => {
        this.updateConnectorPositions();
      });
      this.resizeObserver.observe(this.container);
      const columns = this.container.querySelectorAll('.tier-column');
      columns.forEach((col) => this.resizeObserver?.observe(col));
    }
  }

  private updateMobileBarActiveState(bar: HTMLElement) {
    bar.querySelectorAll('.mobile-tier-btn').forEach(btn => {
      const b = btn as HTMLElement;
      if (this.activeMobileTier === 'all') {
        b.classList.toggle('active', !b.dataset.tierNum);
      } else {
        b.classList.toggle('active', b.dataset.tierNum === String(this.activeMobileTier));
      }
    });
  }

  private renderTierColumn(tier: TierDefinition, classDef: ClassDefinition): HTMLElement {
    const col = document.createElement('div');
    col.className = 'tier-column';
    col.dataset.tierNum = tier.tier.toString();

    const isUnlocked = this.engine.isTierUnlocked(tier.tier);
    col.classList.add(isUnlocked ? 'unlocked' : 'locked');

    // Header
    const header = document.createElement('div');
    header.className = 'tier-header';

    const titleBox = document.createElement('div');
    titleBox.className = 'tier-title-box';

    const title = document.createElement('div');
    title.className = 'tier-name';
    title.textContent = tier.name;
    titleBox.appendChild(title);

    const reqLvl = document.createElement('div');
    reqLvl.className = 'tier-req-level';
    reqLvl.textContent = `Req. Level: ${tier.requiredCharacterLevel}`;
    titleBox.appendChild(reqLvl);

    header.appendChild(titleBox);

    const pointsBadge = document.createElement('div');
    pointsBadge.className = 'tier-points-badge';
    pointsBadge.id = `tier-pts-badge-${tier.tier}`;
    pointsBadge.textContent = `${this.engine.getTierPoints(tier.tier)} pts`;
    header.appendChild(pointsBadge);

    col.appendChild(header);

    // Lock Overlay Banner if locked
    const lockBanner = document.createElement('div');
    lockBanner.className = 'tier-lock-banner';
    lockBanner.id = `tier-lock-banner-${tier.tier}`;
    lockBanner.style.display = isUnlocked ? 'none' : 'flex';

    const req = this.engine.getTierUnlockRequirement(tier.tier);
    const reqText = req
      ? `Requires ${req.required} points in ${req.prevTierName} (${req.current}/${req.required})`
      : 'Locked';
    lockBanner.innerHTML = `<span class="tier-lock-icon">🔒</span><span>${reqText}</span>`;
    col.appendChild(lockBanner);

    // Skills Matrix Body
    const body = document.createElement('div');
    body.className = 'tier-body';

    // SVG connector lines layer matching Tome style
    const svgLayer = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svgLayer.setAttribute('class', 'tier-svg-connectors');

    const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
    defs.innerHTML = `
      <marker id="tier-arrow-default-${tier.tier}" viewBox="0 0 10 8" refX="9" refY="4" markerWidth="8" markerHeight="6" orient="auto">
        <path d="M 0 0.5 L 2.5 4 L 0 7.5 L 10 4 Z" fill="#9d7b3e" stroke="#3a2a16" stroke-width="0.5" />
      </marker>
      <marker id="tier-arrow-available-${tier.tier}" viewBox="0 0 10 8" refX="9" refY="4" markerWidth="8" markerHeight="6" orient="auto">
        <path d="M 0 0.5 L 2.5 4 L 0 7.5 L 10 4 Z" fill="#dfc27d" stroke="#4a3710" stroke-width="0.5" />
      </marker>
      <marker id="tier-arrow-active-${tier.tier}" viewBox="0 0 10 8" refX="9" refY="4" markerWidth="8" markerHeight="6" orient="auto">
        <path d="M 0 0.5 L 2.5 4 L 0 7.5 L 10 4 Z" fill="#ffd573" stroke="#5a4520" stroke-width="0.5" />
      </marker>
    `;
    svgLayer.appendChild(defs);

    for (const skill of tier.skills) {
      if (skill.prerequisites && skill.prerequisites.length > 0) {
        for (const prereq of skill.prerequisites) {
          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          path.setAttribute('class', 'tier-connector-line');
          path.setAttribute('fill', 'none');
          path.setAttribute('marker-end', `url(#tier-arrow-default-${tier.tier})`);
          path.dataset.parentId = prereq.skillId;
          path.dataset.childId = skill.id;
          path.dataset.requiredRank = String(prereq.requiredRank || 1);
          path.dataset.tierNum = String(tier.tier);
          svgLayer.appendChild(path);
        }
      }
    }
    body.appendChild(svgLayer);

    const matrix = document.createElement('div');
    matrix.className = 'skills-matrix';

    // Normalize tier layout: if tier has an empty row 1, promote center root skill to row 1
    const hasRow1 = tier.skills.some(s => s.row === 1);
    if (!hasRow1) {
      const rootSkill = tier.skills.find(s => s.row === 2 && s.col === 2 && (!s.prerequisites || s.prerequisites.length === 0));
      if (rootSkill) {
        rootSkill.row = 1;
        rootSkill.top = 19;
      }
    }

    // Sort skills by row, then col
    const sortedSkills = [...tier.skills].sort((a, b) => {
      if (a.row !== b.row) return a.row - b.row;
      return a.col - b.col;
    });

    for (const skill of sortedSkills) {
      const node = new SkillNode(skill, this.engine);
      this.skillNodes.push(node);
      matrix.appendChild(node.getElement());
    }

    body.appendChild(matrix);

    // Reset Tier button in footer
    const footer = document.createElement('div');
    footer.className = 'tier-footer';
    const resetTierBtn = document.createElement('button');
    resetTierBtn.className = 'jd-btn';
    resetTierBtn.style.fontSize = '0.7rem';
    resetTierBtn.style.padding = '4px 8px';
    resetTierBtn.textContent = '↺ Reset Tier';
    resetTierBtn.title = `Reset points spent in ${tier.name}`;
    resetTierBtn.addEventListener('click', () => {
      this.engine.resetTier(tier.tier);
    });
    footer.appendChild(resetTierBtn);
    body.appendChild(footer);

    col.appendChild(body);
    return col;
  }

  public updateConnectorPositions() {
    const columns = this.container.querySelectorAll('.tier-column');
    columns.forEach((colEl) => {
      const col = colEl as HTMLElement;
      const body = col.querySelector('.tier-body') as HTMLElement;
      if (!body) return;
      const bodyRect = body.getBoundingClientRect();
      if (bodyRect.width === 0 || bodyRect.height === 0) return;

      const paths = body.querySelectorAll('.tier-connector-line');
      paths.forEach((pathEl) => {
        const path = pathEl as SVGPathElement;
        const parentId = path.dataset.parentId;
        const childId = path.dataset.childId;
        if (!parentId || !childId) return;

        const parentNode = body.querySelector(`.skill-node[data-skill-id="${parentId}"]`) as HTMLElement;
        const childNode = body.querySelector(`.skill-node[data-skill-id="${childId}"]`) as HTMLElement;
        if (!parentNode || !childNode) return;

        const pFrame = parentNode.querySelector('.skill-slot-frame') as HTMLElement;
        const cFrame = childNode.querySelector('.skill-slot-frame') as HTMLElement;
        if (!pFrame || !cFrame) return;

        const pRect = pFrame.getBoundingClientRect();
        const cRect = cFrame.getBoundingClientRect();
        const pNodeRect = parentNode.getBoundingClientRect();

        const pCenterX = (pRect.left + pRect.right) / 2 - bodyRect.left;
        const pCenterY = (pRect.top + pRect.bottom) / 2 - bodyRect.top;

        const cCenterX = (cRect.left + cRect.right) / 2 - bodyRect.left;
        const cCenterY = (cRect.top + cRect.bottom) / 2 - bodyRect.top;

        const dx = cCenterX - pCenterX;
        const dy = cCenterY - pCenterY;

        // Straight downward connectors (same column)
        if (Math.abs(dx) < 12 && dy > 0) {
          const startX = Math.round(pCenterX);
          const startY = Math.round(pNodeRect.bottom - bodyRect.top + 3);
          const endX = Math.round(cCenterX);
          const endY = Math.round(cRect.top - bodyRect.top - 2);

          path.setAttribute('d', `M ${startX} ${startY} L ${endX} ${endY}`);
        } else {
          // Diagonal / branching connectors:
          // Start halfway up the side of the top (parent) icon with breathing room so they don't touch
          const startX = Math.round(dx < 0 ? pRect.left - bodyRect.left - 6 : pRect.right - bodyRect.left + 6);
          const startY = Math.round(pCenterY);

          // End point: center-top of the child frame
          const endX = Math.round(cCenterX);
          const endY = Math.round(cRect.top - bodyRect.top - 2);

          const cdy = endY - startY;

          // Single uniform parabolic curve (Quadratic Bezier):
          // Control point cp has cpX = endX, ensuring the curve enters 100% straight down
          const cpX = endX;
          const cpY = Math.round(startY + cdy * 0.08);

          path.setAttribute('d', `M ${startX} ${startY} Q ${cpX} ${cpY}, ${endX} ${endY}`);
        }
      });
    });
  }

  private updateConnectorStates() {
    const paths = this.container.querySelectorAll('.tier-connector-line');
    paths.forEach((pathEl) => {
      const path = pathEl as SVGPathElement;
      const parentId = path.dataset.parentId;
      const childId = path.dataset.childId;
      const reqRank = parseInt(path.dataset.requiredRank || '1', 10);
      const tierNum = path.dataset.tierNum || '0';

      if (parentId && childId) {
        const parentRank = this.engine.getRank(parentId);
        const childRank = this.engine.getRank(childId);

        const isActive = parentRank >= reqRank && childRank > 0;
        const isAvailable = parentRank >= reqRank && childRank === 0;

        path.classList.toggle('active', isActive);
        path.classList.toggle('available', isAvailable);

        if (isActive) {
          path.setAttribute('marker-end', `url(#tier-arrow-active-${tierNum})`);
        } else if (isAvailable) {
          path.setAttribute('marker-end', `url(#tier-arrow-available-${tierNum})`);
        } else {
          path.setAttribute('marker-end', `url(#tier-arrow-default-${tierNum})`);
        }
      }
    });
  }

  private onEngineUpdate() {
    // Update individual nodes
    for (const node of this.skillNodes) {
      node.updateState();
    }

    this.updateConnectorStates();
    this.updateConnectorPositions();

    // Update tier badges and lock banners
    const classDef = this.engine.getClassDefinition();
    for (const tier of classDef.tiers) {
      const pts = this.engine.getTierPoints(tier.tier);
      const badge = document.getElementById(`tier-pts-badge-${tier.tier}`);
      if (badge) {
        badge.textContent = `${pts} pts`;
      }

      const mobilePts = document.getElementById(`mobile-tier-pts-${tier.tier}`);
      if (mobilePts) {
        mobilePts.textContent = `(${pts})`;
      }

      const lockBanner = document.getElementById(`tier-lock-banner-${tier.tier}`);
      const col = this.container.querySelector(`.tier-column[data-tier-num="${tier.tier}"]`);
      const isUnlocked = this.engine.isTierUnlocked(tier.tier);

      if (col) {
        col.classList.toggle('unlocked', isUnlocked);
        col.classList.toggle('locked', !isUnlocked);
      }

      if (lockBanner) {
        lockBanner.style.display = isUnlocked ? 'none' : 'flex';
        if (!isUnlocked) {
          const req = this.engine.getTierUnlockRequirement(tier.tier);
          const reqText = req
            ? `Requires ${req.required} points in ${req.prevTierName} (${req.current}/${req.required})`
            : 'Locked';
          lockBanner.innerHTML = `<span class="tier-lock-icon">🔒</span><span>${reqText}</span>`;
        }
      }
    }
  }
}
