/**
 * Returns affinity skills available for a class and chosen affinity.
 */
export function getAffinitySkills(classId: string, affinity: Affinity): AffinitySkill[] {
  if (affinity === 'none') return [];
  const def = AFFINITY_DEFINITIONS[affinity];
  if (!def) return [];

  const general = def.generalSkills || [];
  const classTree = CLASS_AFFINITY_SKILLS[classId]?.[affinity] || [];

  return [...general, ...classTree];
}

