import { SkillEngine } from '../../engine/SkillEngine.ts';
import { Affinity, Skill } from '../../types/skill.ts';
import { 
  AFFINITY_DEFINITIONS, 
  CLASS_AFFINITY_SKILLS, 
  AffinitySkill, 
  ChromaSkill, 
  getChromaSkills 
} from '../../data/skills/affinity.ts';
import { SkillTooltip } from './SkillTooltip.ts';

export class AffinityTreeRenderer {
  private container: HTMLElement;
  private engine: SkillEngine;
  private affinityAllocations: Record<string, number> = {};
  private chromaAllocations: Record<string, number> = {};
  private activeSubTab: 'affinity' | 'chroma' = 'affinity';
  private chromaLevel: number = 81;

  constructor(container: HTMLElement, engine: SkillEngine) {
    this.container = container;
    this.engine = engine;
    this.render();
    this.engine.subscribe(this.render.bind(this));
  }

  public setEngine(engine: SkillEngine) {
    this.engine = engine;
    this.render();
    this.engine.subscribe(this.render.bind(this));
  }

  public render() {
    this.container.innerHTML = '';
    const isAscended = this.engine.isAscendedMode();
    const activeAffinity = this.engine.getAffinity();
    const classDef = this.engine.getClassDefinition();

    // 1. Locked State: Character is not Ascended
    if (!isAscended) {
      this.container.innerHTML = `
        <div class="affinity-locked-card">
          <div class="affinity-lock-icon">🔒</div>
          <h3 class="affinity-lock-title">Ascension & Affinity Required</h3>
          <p class="affinity-lock-desc">
            Affinity abilities are unlocked upon <strong>Ascension</strong> at Level 90. 
            Ascended cultivators align with <strong>Dagos</strong>, <strong>Felkin</strong>, or <strong>Fuwa</strong> 
            to awaken general affinity passives and tier II signature faction masteries.
          </p>
          <button class="jd-btn btn-primary" id="btn-unlock-ascended-from-tree">
            ✨ Ascend Character (175 SP / 64 TP)
          </button>
        </div>
      `;
      this.container.querySelector('#btn-unlock-ascended-from-tree')?.addEventListener('click', () => {
        this.engine.setAscended(true);
      });
      return;
    }

    // 2. Ascended, but no Affinity chosen yet
    if (activeAffinity === 'none') {
      this.container.innerHTML = `
        <div class="affinity-selection-view">
          <div class="affinity-prompt-header">
            <span class="affinity-prompt-badge">Ascended Level 90+</span>
            <h3 class="affinity-prompt-title">Choose Your Affinity</h3>
            <p class="affinity-prompt-desc">
              Select one of the three cosmic paths to awaken specialized combat enhancements and legendary Tier II faction skills.
            </p>
          </div>

          <div class="affinity-cards-grid">
            <!-- Dagos -->
            <div class="affinity-choice-card dagos-card" id="card-pick-dagos">
              <div class="aff-card-header">
                <span class="aff-symbol">☀️</span>
                <div>
                  <h4 class="aff-name">Dagos</h4>
                  <span class="aff-title">The Celestial Immortals</span>
                </div>
              </div>
              <p class="aff-blurb">
                Attune to heavenly lightning and pure celestial energy. Extreme critical strike dominance, sprint mobility, and single-target/AoE burst.
              </p>
              <div class="aff-bonus-tag">
                ⚡ +15% Crit Rate • +30% Crit DMG • +1.5m/s Speed
              </div>
              <button class="jd-btn btn-primary aff-select-btn" data-aff="dagos">
                Select Dagos
              </button>
            </div>

            <!-- Felkin -->
            <div class="affinity-choice-card felkin-card" id="card-pick-felkin">
              <div class="aff-card-header">
                <span class="aff-symbol">🌙</span>
                <div>
                  <h4 class="aff-name">Felkin</h4>
                  <span class="aff-title">The Abyssal Dominion</span>
                </div>
              </div>
              <p class="aff-blurb">
                Wield abyssal dark magic, crippling curses, and unstoppable bleeds. Shreds enemy defenses and burns target Spirit with lethal execution strikes.
              </p>
              <div class="aff-bonus-tag">
                🩸 +20% Bleed • -25% Target Defense • Anti-Heal Curses
              </div>
              <button class="jd-btn btn-primary aff-select-btn" data-aff="felkin">
                Select Felkin
              </button>
            </div>

            <!-- Fuwa -->
            <div class="affinity-choice-card fuwa-card" id="card-pick-fuwa">
              <div class="aff-card-header">
                <span class="aff-symbol">🪷</span>
                <div>
                  <h4 class="aff-name">Fuwa</h4>
                  <span class="aff-title">The Pure Zen Guardians</span>
                </div>
              </div>
              <p class="aff-blurb">
                Attain Buddhist tranquility and diamond durability. Immense health pools, invulnerability barriers, damage reflection, and CC immunity.
              </p>
              <div class="aff-bonus-tag">
                🛡️ +25% Max HP • +40 All Resists • Damage Reflection
              </div>
              <button class="jd-btn btn-primary aff-select-btn" data-aff="fuwa">
                Select Fuwa
              </button>
            </div>
          </div>
        </div>
      `;

      this.container.querySelectorAll('.aff-select-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
          const aff = (e.currentTarget as HTMLElement).dataset.aff as Affinity;
          if (aff) this.engine.setAffinity(aff);
        });
      });
      return;
    }

    // 3. Affinity Selected: Render Full Tree
    const affDef = AFFINITY_DEFINITIONS[activeAffinity];
    const generalSkills = affDef.generalSkills;
    const classSkills = CLASS_AFFINITY_SKILLS[classDef.id]?.[activeAffinity] || [];
    const chromaSkills = getChromaSkills(activeAffinity);

    const totalAffPoints = Object.values(this.affinityAllocations).reduce((sum, n) => sum + n, 0);
    const totalChromaPoints = Object.values(this.chromaAllocations).reduce((sum, n) => sum + n, 0);

    const treeWrapper = document.createElement('div');
    treeWrapper.className = `affinity-active-tree theme-${activeAffinity}`;

    // Top In-Game Affinity Banner with Switcher & Sub-tabs
    const banner = document.createElement('div');
    banner.className = 'affinity-active-banner';
    banner.innerHTML = `
      <div class="aff-banner-info">
        <span class="aff-banner-icon">${affDef.icon}</span>
        <div>
          <div class="aff-banner-headline">
            <h3>${affDef.name} Affinity</h3>
            <span class="aff-banner-tag">${affDef.title}</span>
          </div>
          <p class="aff-banner-combat-bonus"><strong>Resonance:</strong> ${affDef.combatBonus}</p>
        </div>
      </div>

      <div class="aff-center-subtabs">
        <button class="aff-subtab-btn ${this.activeSubTab === 'affinity' ? 'active' : ''}" id="btn-subtab-aff">
          ✨ Affinity Masteries <span class="subtab-count">(${totalAffPoints} pts)</span>
        </button>
        <button class="aff-subtab-btn ${this.activeSubTab === 'chroma' ? 'active' : ''}" id="btn-subtab-chroma">
          🔮 Chroma Abilities <span class="subtab-count">(${totalChromaPoints}/80 pts)</span>
        </button>
      </div>

      <div class="aff-switcher-group">
        <span class="aff-switch-label">Switch Affinity:</span>
        <div class="aff-switch-buttons">
          <button class="aff-pill-btn ${activeAffinity === 'dagos' ? 'active' : ''}" data-aff="dagos" title="Switch to Dagos">☀️ Dagos</button>
          <button class="aff-pill-btn ${activeAffinity === 'felkin' ? 'active' : ''}" data-aff="felkin" title="Switch to Felkin">🌙 Felkin</button>
          <button class="aff-pill-btn ${activeAffinity === 'fuwa' ? 'active' : ''}" data-aff="fuwa" title="Switch to Fuwa">🪷 Fuwa</button>
        </div>
      </div>
    `;

    banner.querySelectorAll('.aff-pill-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const aff = (e.currentTarget as HTMLElement).dataset.aff as Affinity;
        if (aff) this.engine.setAffinity(aff);
      });
    });

    banner.querySelector('#btn-subtab-aff')?.addEventListener('click', () => {
      this.activeSubTab = 'affinity';
      this.render();
    });

    banner.querySelector('#btn-subtab-chroma')?.addEventListener('click', () => {
      this.activeSubTab = 'chroma';
      this.render();
    });

    treeWrapper.appendChild(banner);

    // ==========================================
    // VIEW A: AFFINITY MASTERIES (General + Class Tier II)
    // ==========================================
    if (this.activeSubTab === 'affinity') {
      const contentContainer = document.createElement('div');
      contentContainer.className = 'affinity-subtab-content';

      // Section 1: General Affinity Abilities (In-game slot grid)
      const genSection = document.createElement('div');
      genSection.className = 'affinity-section';
      genSection.innerHTML = `
        <div class="affinity-section-heading">
          <span class="section-badge">${affDef.name} Universal</span>
          <h4>${affDef.name} Universal Masteries</h4>
          <span class="section-sub">Cosmic passives and blessings accessible to all ${affDef.name} cultivators</span>
        </div>
        <div class="affinity-slots-grid" id="grid-aff-general"></div>
      `;
      const genGrid = genSection.querySelector('#grid-aff-general')!;
      for (const skill of generalSkills) {
        genGrid.appendChild(this.createSkillSlotNode(skill, 'affinity'));
      }
      contentContainer.appendChild(genSection);

      // Section 2: Signature Tier II Class Skills (In-game slot grid)
      const classSection = document.createElement('div');
      classSection.className = 'affinity-section';
      classSection.innerHTML = `
        <div class="affinity-section-heading">
          <span class="section-badge">${classDef.name} Exclusive</span>
          <h4>${classDef.name} Tier II Masteries</h4>
          <span class="section-sub">Ascended awakenings of signature ${classDef.name} arts fused with ${affDef.name} energy</span>
        </div>
        <div class="affinity-slots-grid" id="grid-aff-class"></div>
      `;
      const classGrid = classSection.querySelector('#grid-aff-class')!;
      for (const skill of classSkills) {
        classGrid.appendChild(this.createSkillSlotNode(skill, 'affinity'));
      }
      contentContainer.appendChild(classSection);

      treeWrapper.appendChild(contentContainer);
    }

    // ==========================================
    // VIEW B: CHROMA SYSTEM
    // ==========================================
    if (this.activeSubTab === 'chroma') {
      const chromaContainer = document.createElement('div');
      chromaContainer.className = 'affinity-subtab-content chroma-content-view';

      // Chroma Dashboard Bar
      const chromaBar = document.createElement('div');
      chromaBar.className = 'chroma-control-dashboard';
      chromaBar.innerHTML = `
        <div class="chroma-dash-col">
          <span class="chroma-dash-label">Chroma Realm</span>
          <span class="chroma-dash-val">CHROMA • ${activeAffinity.toUpperCase()}</span>
        </div>
        <div class="chroma-dash-col">
          <span class="chroma-dash-label">Chroma Level</span>
          <div class="chroma-level-control">
            <span class="chroma-level-display">Lv. ${this.chromaLevel}</span>
            <input type="range" class="chroma-slider" id="chroma-level-slider" min="1" max="81" value="${this.chromaLevel}" />
          </div>
        </div>
        <div class="chroma-dash-col">
          <span class="chroma-dash-label">Chroma Points Spent</span>
          <span class="chroma-dash-val highlight">${totalChromaPoints} / 80</span>
        </div>
        <div class="chroma-dash-col">
          <button class="jd-btn btn-sm" id="btn-reset-chroma-pts" title="Reset all spent Chroma points">
            ↺ Reset Chroma
          </button>
        </div>
      `;

      chromaBar.querySelector('#chroma-level-slider')?.addEventListener('input', (e) => {
        this.chromaLevel = Number((e.target as HTMLInputElement).value);
        const disp = chromaBar.querySelector('.chroma-level-display');
        if (disp) disp.textContent = `Lv. ${this.chromaLevel}`;
      });

      chromaBar.querySelector('#btn-reset-chroma-pts')?.addEventListener('click', () => {
        this.chromaAllocations = {};
        this.render();
      });

      chromaContainer.appendChild(chromaBar);

      // Chroma Skills Section
      const chromaSection = document.createElement('div');
      chromaSection.className = 'affinity-section';
      chromaSection.innerHTML = `
        <div class="affinity-section-heading">
          <span class="section-badge">Ascended Lv. 120+</span>
          <h4>${affDef.name} Chroma Masteries</h4>
          <span class="section-sub">Supreme late-game arts that pierce mortal defenses and reshape the battlefield</span>
        </div>
        <div class="affinity-slots-grid chroma-grid" id="grid-chroma-skills"></div>
      `;
      const chromaGrid = chromaSection.querySelector('#grid-chroma-skills')!;
      for (const skill of chromaSkills) {
        chromaGrid.appendChild(this.createSkillSlotNode(skill, 'chroma'));
      }
      chromaContainer.appendChild(chromaSection);

      treeWrapper.appendChild(chromaContainer);
    }

    this.container.appendChild(treeWrapper);
  }

  /**
   * Creates an authentic in-game Jade Dynasty skill slot node with metallic border,
   * stepper controls row with rank badge directly underneath, and hover tooltip.
   */
  private createSkillSlotNode(skill: AffinitySkill | ChromaSkill, type: 'affinity' | 'chroma'): HTMLElement {
    const allocations = type === 'affinity' ? this.affinityAllocations : this.chromaAllocations;
    const currentRank = allocations[skill.id] || 0;
    const isMax = currentRank >= skill.maxRank;

    const node = document.createElement('div');
    node.className = `in-game-skill-slot-card ${currentRank > 0 ? 'invested' : ''} ${isMax ? 'maxed' : ''}`;
    node.dataset.skillId = skill.id;

    // Determine icon rendering: sprite sheet vs individual PNG
    const base = import.meta.env.BASE_URL || './';
    const cleanIcon = skill.icon.startsWith('/') ? skill.icon.slice(1) : skill.icon.replace(/^\.\//, '');
    const assetPath = `${base}${cleanIcon}`;

    let coords = skill.spriteCoords;
    if (!coords && skill.icon.endsWith('.jpg')) {
      const classDef = this.engine.getClassDefinition();
      const baseName = skill.name.replace(/\s+II$/i, '').trim().toLowerCase();
      if (classDef?.tiers) {
        for (const t of classDef.tiers) {
          for (const s of t.skills) {
            const sName = s.name.toLowerCase();
            if (sName === baseName || sName.includes(baseName) || baseName.includes(sName)) {
              if (s.spriteCoords) {
                coords = s.spriteCoords;
                break;
              }
            }
          }
          if (coords) break;
        }
      }
    }

    let iconInnerHtml = '';
    if (coords) {
      iconInnerHtml = `
        <div class="skill-icon-sprite" style="background-image: url('${assetPath}'); background-position: -${coords.x}px -${coords.y}px;"></div>
      `;
    } else if (skill.icon.endsWith('.jpg')) {
      const x = ((skill.col || 1) - 1) * 36;
      const y = ((skill.row || 1) - 1) * 36;
      iconInnerHtml = `
        <div class="skill-icon-sprite" style="background-image: url('${assetPath}'); background-position: -${x}px -${y}px;"></div>
      `;
    } else {
      iconInnerHtml = `
        <img src="${assetPath}" class="skill-icon-img" alt="${skill.name}" loading="lazy" onerror="this.onerror=null; this.src='${base}assets/icons/0.png';" />
      `;
    }

    node.innerHTML = `
      <div class="skill-slot-frame">
        ${iconInnerHtml}
      </div>
      <div class="skill-controls-row">
        <button type="button" class="jd-step-btn btn-minus ${currentRank === 0 ? 'disabled' : ''}" title="Remove point">−</button>
        <span class="skill-rank-badge ${currentRank > 0 ? 'active' : ''}">${currentRank}/${skill.maxRank}</span>
        <button type="button" class="jd-step-btn btn-plus ${isMax ? 'disabled' : ''}" title="Add point">+</button>
      </div>
      <div class="skill-name-label">${skill.name}</div>
    `;

    // Tooltip integration on icon frame
    const frameEl = node.querySelector('.skill-slot-frame') as HTMLElement;
    frameEl.addEventListener('mouseenter', () => {
      SkillTooltip.getInstance().showAffinitySkill(skill, currentRank, this.engine);
    });
    frameEl.addEventListener('mouseleave', () => {
      SkillTooltip.getInstance().hide();
    });

    // Rank controls
    const incBtn = node.querySelector('.btn-plus') as HTMLButtonElement;
    const decBtn = node.querySelector('.btn-minus') as HTMLButtonElement;

    incBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.incrementRank(skill, type);
    });

    decBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.decrementRank(skill, type);
    });

    // Left-click icon: on mobile open tooltip, on desktop add point
    frameEl.addEventListener('click', (e) => {
      e.stopPropagation();
      if (window.innerWidth <= 768) {
        SkillTooltip.getInstance().showAffinitySkill(skill, currentRank, this.engine);
      } else {
        this.incrementRank(skill, type);
      }
    });

    // Right-click icon: decrement rank
    frameEl.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.decrementRank(skill, type);
    });

    return node;
  }

  private incrementRank(skill: Skill, type: 'affinity' | 'chroma') {
    const allocations = type === 'affinity' ? this.affinityAllocations : this.chromaAllocations;
    const current = allocations[skill.id] || 0;

    if (type === 'chroma') {
      const totalChroma = Object.values(this.chromaAllocations).reduce((sum, n) => sum + n, 0);
      if (totalChroma >= 80) return;
    }

    if (current < skill.maxRank) {
      allocations[skill.id] = current + 1;
      this.render();
    }
  }

  private decrementRank(skill: Skill, type: 'affinity' | 'chroma') {
    const allocations = type === 'affinity' ? this.affinityAllocations : this.chromaAllocations;
    const current = allocations[skill.id] || 0;
    if (current > 0) {
      allocations[skill.id] = current - 1;
      this.render();
    }
  }
}
