import { SavedBuild, ClassDefinition, BuildAllocation, TomeAllocation, Character } from '../types/skill.ts';
import { UrlSerializer } from './UrlSerializer.ts';

const STORAGE_KEY_CHARACTERS = 'jade_compendium_characters';
const STORAGE_KEY_BUILDS = 'jade_compendium_saved_builds';
const STORAGE_KEY_AUTOSAVE_PREFIX = 'jade_compendium_autosave_';
const STORAGE_KEY_LAST_CLASS = 'jade_compendium_last_class';

export class StorageManager {
  private static hasMigrated = false;

  private static checkMigration(): void {
    if (this.hasMigrated) return;
    this.hasMigrated = true;
    try {
      const rawBuilds = localStorage.getItem(STORAGE_KEY_BUILDS);
      if (rawBuilds) {
        const builds: SavedBuild[] = JSON.parse(rawBuilds);
        if (Array.isArray(builds) && builds.length > 0) {
          const chars = this.getCharacters();
          const existingNames = new Set(chars.map(c => `${c.classId}_${c.name.toLowerCase()}`));
          let changed = false;
          for (const b of builds) {
            const key = `${b.classId}_${b.name.toLowerCase()}`;
            if (!existingNames.has(key)) {
              chars.push({
                id: b.id || 'char_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
                name: b.name,
                classId: b.classId,
                createdAt: b.timestamp || Date.now(),
                updatedAt: b.timestamp || Date.now(),
                allocation: b.allocation || {},
                tomeAllocation: b.tomeAllocation || {}
              });
              existingNames.add(key);
              changed = true;
            }
          }
          if (changed) {
            localStorage.setItem(STORAGE_KEY_CHARACTERS, JSON.stringify(chars));
            localStorage.setItem('jade_compendium_user_created', 'true');
          }
        }
      }
    } catch {
      // Ignore
    }
  }

  public static getSavedBuilds(classId?: string): SavedBuild[] {
    this.checkMigration();
    const chars = this.getCharacters();
    const builds: SavedBuild[] = chars.map(c => {
      let totalPoints = 0;
      for (const pts of Object.values(c.allocation || {})) {
        totalPoints += pts;
      }
      let totalTomePoints = 0;
      for (const pts of Object.values(c.tomeAllocation || {})) {
        totalTomePoints += pts;
      }
      return {
        id: c.id,
        name: c.name,
        classId: c.classId,
        timestamp: c.updatedAt || c.createdAt || Date.now(),
        totalPoints,
        totalTomePoints,
        allocation: c.allocation || {},
        tomeAllocation: c.tomeAllocation || {},
        isAscended: c.isAscended || false,
        affinity: c.affinity || 'none',
        hashString: ''
      };
    });

    if (classId) {
      return builds.filter(b => b.classId === classId);
    }
    return builds;
  }

  public static saveBuild(
    name: string,
    classDef: ClassDefinition,
    allocation: BuildAllocation,
    tomeAllocation: TomeAllocation = {},
    notes?: string,
    isAscended: boolean = false,
    affinity: Affinity = 'none'
  ): SavedBuild {
    this.checkMigration();
    const cleanName = name.trim() || `${classDef.name} Build`;
    const chars = this.getCharacters();
    const activeId = this.getActiveCharacterId();

    // Look for currently active character matching class, or matching name+class
    const existing = chars.find(c => c.id === activeId && c.classId === classDef.id) ||
                     chars.find(c => c.name.toLowerCase() === cleanName.toLowerCase() && c.classId === classDef.id);

    let targetChar: Character;
    if (existing) {
      existing.name = cleanName;
      existing.allocation = allocation;
      existing.tomeAllocation = tomeAllocation;
      existing.isAscended = isAscended;
      existing.affinity = affinity;
      existing.updatedAt = Date.now();
      targetChar = existing;
      try {
        localStorage.setItem(STORAGE_KEY_CHARACTERS, JSON.stringify(chars));
        this.setActiveCharacterId(existing.id);
      } catch {}
    } else {
      targetChar = this.createCharacter(cleanName, classDef.id, allocation, tomeAllocation, isAscended, affinity);
    }

    let totalPoints = 0;
    for (const pts of Object.values(allocation)) totalPoints += pts;
    let totalTomePoints = 0;
    for (const pts of Object.values(tomeAllocation)) totalTomePoints += pts;

    const hashString = UrlSerializer.encode(classDef, allocation, tomeAllocation, isAscended, affinity);
    return {
      id: targetChar.id,
      name: targetChar.name,
      classId: targetChar.classId,
      timestamp: targetChar.updatedAt,
      totalPoints,
      totalTomePoints,
      allocation,
      tomeAllocation,
      isAscended,
      affinity,
      hashString,
      notes
    };
  }

  public static deleteBuild(id: string): boolean {
    return this.deleteCharacter(id);
  }

  public static getBuildById(id: string): SavedBuild | null {
    const builds = this.getSavedBuilds();
    return builds.find(b => b.id === id) || null;
  }

  public static autoSave(classId: string, allocation: BuildAllocation, tomeAllocation: TomeAllocation = {}) {
    try {
      localStorage.setItem(STORAGE_KEY_AUTOSAVE_PREFIX + classId, JSON.stringify({ allocation, tomeAllocation }));
    } catch {
      // Ignore quota error
    }
  }

  public static getAutoSave(classId: string): { allocation: BuildAllocation; tomeAllocation: TomeAllocation } | null {
    try {
      const raw = localStorage.getItem(STORAGE_KEY_AUTOSAVE_PREFIX + classId);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === 'object') {
        if ('allocation' in parsed) {
          return { allocation: parsed.allocation || {}, tomeAllocation: parsed.tomeAllocation || {} };
        }
        return { allocation: parsed, tomeAllocation: {} };
      }
      return null;
    } catch {
      return null;
    }
  }

  public static setLastClass(classId: string) {
    try {
      localStorage.setItem(STORAGE_KEY_LAST_CLASS, classId);
    } catch {
      // Ignore
    }
  }

  public static getLastClass(): string | null {
    try {
      return localStorage.getItem(STORAGE_KEY_LAST_CLASS);
    } catch {
      return null;
    }
  }

  public static exportBuildsAsJson(): string {
    const builds = this.getSavedBuilds();
    return JSON.stringify(builds, null, 2);
  }

  public static importBuildsFromJson(jsonStr: string): number {
    try {
      const imported: any[] = JSON.parse(jsonStr);
      if (!Array.isArray(imported)) return 0;
      let count = 0;
      for (const b of imported) {
        if (b.name && b.classId && (b.allocation || b.tomeAllocation)) {
          this.createCharacter(
            b.name,
            b.classId,
            b.allocation || {},
            b.tomeAllocation || {}
          );
          count++;
        }
      }
      return count;
    } catch {
      return 0;
    }
  }

  // ===================== MULTIPLE CHARACTERS SYSTEM =====================
  public static getCharacters(): Character[] {
    try {
      const raw = localStorage.getItem('jade_compendium_characters');
      if (!raw) {
        return [];
      }
      const chars: Character[] = JSON.parse(raw);
      if (!Array.isArray(chars) || chars.length === 0) {
        return [];
      }
      // Migration: clean up any legacy auto-seeded "My Jadeon" dummy character
      // that was automatically created if user hasn't explicitly created one
      if (
        chars.length === 1 &&
        chars[0].name.startsWith('My ') &&
        Object.keys(chars[0].allocation || {}).length === 0 &&
        !localStorage.getItem('jade_compendium_user_created')
      ) {
        localStorage.removeItem('jade_compendium_characters');
        localStorage.removeItem('jade_compendium_active_character_id');
        return [];
      }
      return chars;
    } catch {
      return [];
    }
  }

  public static getActiveCharacterId(): string | null {
    try {
      return localStorage.getItem('jade_compendium_active_character_id');
    } catch {
      return null;
    }
  }

  public static setActiveCharacterId(id: string | null): void {
    try {
      if (id) {
        localStorage.setItem('jade_compendium_active_character_id', id);
      } else {
        localStorage.removeItem('jade_compendium_active_character_id');
      }
    } catch {
      // Ignore
    }
  }

  public static getActiveCharacter(): Character | null {
    const chars = this.getCharacters();
    if (chars.length === 0) return null;
    const activeId = this.getActiveCharacterId();
    const found = chars.find(c => c.id === activeId);
    if (found) return found;
    // Fallback to first character
    this.setActiveCharacterId(chars[0].id);
    return chars[0];
  }

  public static createCharacter(
    name: string,
    classId: string,
    allocation: BuildAllocation = {},
    tomeAllocation: TomeAllocation = {},
    isAscended: boolean = false,
    affinity: Affinity = 'none'
  ): Character {
    const chars = this.getCharacters();
    const newChar: Character = {
      id: 'char_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
      name: name.trim() || `New ${classId.charAt(0).toUpperCase() + classId.slice(1)}`,
      classId,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      allocation,
      tomeAllocation,
      isAscended,
      affinity
    };

    chars.unshift(newChar);
    try {
      localStorage.setItem('jade_compendium_user_created', 'true');
      localStorage.setItem('jade_compendium_characters', JSON.stringify(chars));
      this.setActiveCharacterId(newChar.id);
      this.setLastClass(classId);
    } catch {
      // Ignore
    }
    return newChar;
  }

  public static updateCharacter(
    id: string,
    allocation: BuildAllocation,
    tomeAllocation: TomeAllocation,
    isAscended?: boolean,
    affinity?: Affinity
  ): void {
    const chars = this.getCharacters();
    const target = chars.find(c => c.id === id);
    if (target) {
      target.allocation = allocation;
      target.tomeAllocation = tomeAllocation;
      if (isAscended !== undefined) target.isAscended = isAscended;
      if (affinity !== undefined) target.affinity = affinity;
      target.updatedAt = Date.now();
      try {
        localStorage.setItem('jade_compendium_characters', JSON.stringify(chars));
      } catch {
        // Ignore
      }
    }
  }

  public static renameCharacter(id: string, newName: string): boolean {
    const chars = this.getCharacters();
    const target = chars.find(c => c.id === id);
    if (target && newName.trim()) {
      target.name = newName.trim();
      target.updatedAt = Date.now();
      try {
        localStorage.setItem('jade_compendium_characters', JSON.stringify(chars));
      } catch {
        // Ignore
      }
      return true;
    }
    return false;
  }

  public static deleteCharacter(id: string): boolean {
    let chars = this.getCharacters();
    const filtered = chars.filter(c => c.id !== id);
    if (filtered.length !== chars.length) {
      try {
        localStorage.setItem('jade_compendium_characters', JSON.stringify(filtered));
        if (this.getActiveCharacterId() === id || filtered.length === 0) {
          const nextId = filtered.length > 0 ? filtered[0].id : null;
          this.setActiveCharacterId(nextId);
        }
      } catch {
        // Ignore
      }
      return true;
    }
    return false;
  }

  public static clearAllCharacters(): void {
    try {
      localStorage.setItem('jade_compendium_characters', JSON.stringify([]));
      this.setActiveCharacterId(null);
    } catch {
      // Ignore
    }
  }
}
